try:
    with open("marks.txt", "r") as f:
        total =0
        count =0
        hmarks =-1
        topper = ""
        for line in f:
            parts = line.strip().split()
            name = parts[0]
            marks = int(parts[1])
            total += marks
            count += 1
            if marks > hmarks:
                hmarks = marks
                topper = name
        average = total / count            
        print("Highest marks ",hmarks)
        print("Average ", average)
        print("Toppe name ", topper)

except FileNotFoundError:
    print("file not found ")        

